import { Handler } from '@use-gesture/react';
import { PickD3Scale } from '@visx/scale';

type DragEvent = PointerEvent | MouseEvent | TouchEvent | KeyboardEvent;

interface PanningConfig {
  onDrag: Handler<'drag', DragEvent> | undefined;
  onDragEnd: Handler<'drag', DragEvent> | undefined;
  onWheel: Handler<'wheel', WheelEvent> | undefined;
  onWheelEnd: Handler<'wheel', WheelEvent> | undefined;
}

const KEYBOARD_HANDLERS = ['keyup', 'keydown'];

interface PanningProp {
  initialXScale: PickD3Scale<'linear' | 'time' | 'log'>;
  xScale: PickD3Scale<'linear' | 'time' | 'log'>;
  onPanning: (domain: (number | Date)[]) => void;
  onPanningEnd?: (domain: (number | Date)[]) => void;
}

function getNextPanDomain(
  initialXScale: PickD3Scale<'linear' | 'time' | 'log'>,
  xScale: PickD3Scale<'linear' | 'time' | 'log'>,
  delta: number,
  isWheel: boolean,
) {
  const [rangeMin, rangeMax] = xScale.range() as [number, number];
  const [initialMin, initialMax] = initialXScale.domain();
  const deltaSign = isWheel ? -1 : 1;
  const newMin = xScale.invert(rangeMin - delta * deltaSign);
  const newMax = xScale.invert(rangeMax - delta * deltaSign);

  return newMin > initialMin && newMax < initialMax
    ? [newMin, newMax]
    : xScale.domain();
}

/**
 * get drag and wheel events to perform a panning and a cursor style state.
 *
 * @param initialXScale - initial scale
 * @param xScale - current scale
 * @param onPanning - handle panning on drag/wheel
 * @param onPanningEnd - handle panning end on drag/wheel
 */
export const usePanning = ({
  initialXScale,
  xScale,
  onPanning,
  onPanningEnd,
}: PanningProp): PanningConfig => {
  const onDrag: Handler<'drag', DragEvent> = (event) => {
    if (KEYBOARD_HANDLERS.includes(event.type)) {
      return;
    }

    const nextDomain = getNextPanDomain(
      initialXScale,
      xScale,
      event.delta[0],
      false,
    );
    onPanning(nextDomain);
  };

  const onDragEnd = () => {
    onPanningEnd?.(xScale.domain());
  };

  const onWheel: Handler<'wheel', WheelEvent> = (event) => {
    const nextDomain = getNextPanDomain(
      initialXScale,
      xScale,
      event.delta[1],
      true,
    );
    onPanning(nextDomain);
  };

  const onWheelEnd = () => {
    onPanningEnd?.(xScale.domain());
  };

  return {
    onDrag,
    onDragEnd,
    onWheel,
    onWheelEnd,
  };
};
